_IDX = {"es": 0, "en": 1, "fr": 2}


def norm_lang(lang: Any) -> str:
    l = str(lang or "es").lower()[:2]
    return l if l in _IDX else "es"


def msg(key: str, lang: Any = "es", **kw: Any) -> str:
    return _M[key][_IDX[norm_lang(lang)]].format(**kw)
